steps.code:
[[extensions]]
name = "Regras de entrega"
handle = "regras-entrega"
type = "function"

  [[extensions.targeting]]
  target = "cart.delivery-options.transform.run"
  input_query = "src/cart_delivery_options_transform_run.graphql"
  export = "cart-delivery-options-transform-run"

query CartDeliveryOptionsTransformRunInput {
  cart {
    cost {
      subtotalAmount {
        amount
      }
    }
    deliveryGroups {
      deliveryAddress {
        countryCode
        provinceCode
      }
      deliveryOptions {
        handle
        title
        cost {
          amount
        }
      }
    }
  }
}

// src/cart_delivery_options_transform_run.js
export function cartDeliveryOptionsTransformRun(input) {
  const operations = [];
  const subtotal = Number(input.cart.cost.subtotalAmount.amount);

  for (const group of input.cart.deliveryGroups) {
    for (const option of group.deliveryOptions) {
      const title = option.title?.toLowerCase() ?? "";

      // 1) esconde o frete expresso em pedidos pequenos
      if (title.includes("expresso") && subtotal < 200) {
        operations.push({ deliveryOptionHide: { deliveryOptionHandle: option.handle } });
        continue;
      }

      // 2) renomeia com o prazo
      if (title.includes("padrão")) {
        operations.push({
          deliveryOptionRename: {
            deliveryOptionHandle: option.handle,
            title: `${option.title} (3 a 5 dias úteis)`,
          },
        });
      }
    }
  }

  return { operations };
}

// reordena: coloca a opção "retirada" na segunda posição da lista
operations.push({
  deliveryOptionMove: { deliveryOptionHandle: retirada.handle, index: 1 },
});
